# Self-contained ProtoTail runner for Kaggle GPU
import base64
import io
import os
import subprocess
import sys
import zipfile

# 1. Unpack code bundle directly into current working directory
BUNDLE_B64 = """"""
target_dir = os.getcwd()
print(f"[Kaggle Bootstrap] Unpacking ProtoTail code into {target_dir}...")
with zipfile.ZipFile(io.BytesIO(base64.b64decode(BUNDLE_B64.encode("ascii")))) as z:
    z.extractall(target_dir)

print("[Kaggle Bootstrap] Code unpacked successfully. Available files:")
for item in os.listdir(target_dir):
    print(" -", item)
sys.stdout.flush()

# 2. Execute training
cmd = [
    sys.executable,
    os.path.join(target_dir, "kaggle_train.py"),
    "--baseline", "simgcd",
    "--dataset-slug", "nguyntrnminhtm/gcd-data",
    "--dataset-name", "cub",
    "--imb-ratio", "20",
    "--epochs", "200",
    "--eval-interval", "5",
    "--kmeans-backend", "faiss_gpu",
    "--kmeans-n-init", "10",
    "--kmeans-max-iter", "300",
    "--batch-size", "128",
    "--run-name", "simgcd_cub_Full_imb20",
]
extra_flags = ['--use-parts', '--enable-pseudo-labeling', '--enable-novel-pseudo', '--novel-prototype-end-epoch', '180', '--anti-collapse-novel-selector', '--adaptive-pseudo-threshold', '--pseudo-confidence-min', '0.5', '--pseudo-mode', 'paper']
cmd.extend(extra_flags)

print("\n[Kaggle Runner] Launching command:\n" + " ".join(cmd) + "\n")
sys.stdout.flush()

process = subprocess.run(cmd)
sys.exit(process.returncode)
